import React, { useState } from "react";
import axios from "axios";

const Chatbot = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { text: input, sender: "user" };
    setMessages([...messages, userMessage]);
    setInput("");
    setLoading(true);

    try {
      const response = await axios.post(
        `https://generativelanguage.googleapis.com/v1/models/gemini-pro:generateContent?key=${process.env.REACT_APP_GEMINI_API_KEY}`,
        {
          contents: [
            {
              role: "user",
              parts: [{ text: input }]
            }
          ]
        },
        { headers: { "Content-Type": "application/json" } }
      );

      const botMessage = {
        text: response.data.candidates?.[0]?.content?.parts?.[0]?.text || "I'm unable to respond.",
        sender: "bot"
      };

      setMessages([...messages, userMessage, botMessage]);
    } catch (error) {
      console.error("Error:", error);
      setMessages([...messages, userMessage, { text: "Error fetching response.", sender: "bot" }]);
    }

    setLoading(false);
  };

  return (
    <div style={{ maxWidth: "400px", margin: "auto", textAlign: "center" }}>
      <h2>Gemini Chatbot</h2>
      <div style={{ height: "300px", overflowY: "auto", border: "1px solid #ccc", padding: "10px" }}>
        {messages.map((msg, index) => (
          <div key={index} style={{ textAlign: msg.sender === "user" ? "right" : "left" }}>
            <b>{msg.sender === "user" ? "You: " : "Gemini: "}</b>
            {msg.text}
          </div>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Type a message..."
        style={{ width: "80%", padding: "5px" }}
      />
      <button onClick={sendMessage} disabled={loading} style={{ padding: "5px 10px", marginLeft: "5px" }}>
        {loading ? "Loading..." : "Send"}
      </button>
    </div>
  );
};

export default Chatbot;
